from pathlib import Path
import json,hashlib
H=Path(__file__).resolve().parent
s=json.loads((H/'review/regression/summary.json').read_text())
t=json.loads((H/'review/prerecorded_metrics.json').read_text())
rows=json.loads((H/'review/session/measurements.json').read_text())
changes=s['changes']
source=H.parent/'centrabus_fast_runtime_v5_continuous_dev_20261020'
